+/// Acquire an exclusive advisory lock on a file.
+///
+/// Returns the open lock file. The lock is held until the file is dropped.
+fn lock_file(path: &Path) -> Result<File> {
+    let file =
+        File::create(path).with_context(|| format!("Failed to create lock file {:?}", path))?;
+
+    #[cfg(unix)]
+    {
+        use std::os::unix::io::AsRawFd;
+        // SAFETY: flock is a POSIX API and file is a valid open descriptor.
+        let ret = unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX) };
+        if ret != 0 {
+            return Err(std::io::Error::last_os_error())
+                .with_context(|| format!("Failed to lock {:?}", path));
+        }
+    }
+
+    Ok(file)
+}
